def request_text(p, r=None):
    r=r or p['request']
    fields=[('Status',r['status']),('Project title',r['title']),('Opportunity / resource',r['opportunity']+' / '+r['resource']),('Intended use',r['use']),('Institution',r['institution']),('PI',r['pi']),('Co-PIs',r['co_pis']),('Project dates',r['dates']),('Course titles',p['courses'][0]['title']+'; '+p['courses'][1]['title']),('Enrollment',r['students']),('Staff accounts',r['staff']),('Keywords',r['keywords']),('Field of science',r['field']),('Supporting grant',r['grant']),('Public overview',r['public_overview']),('Planned work summary',r['summary']),('Resource justification / amount',r['resource_justification']),('Software and assignments',r['requested_software']),('Other available resources',r['other_resources'])]
    return '\n\n'.join(k.upper()+'\n'+v for k,v in fields)+'\n\nREQUIRED COMPLETION / ATTACHMENTS\n'+'\n'.join('- '+x for x in r['attachments'])+'\n\nREVIEW AND SUBMISSION STEPS\n'+'\n'.join(str(i+1)+'. '+x for i,x in enumerate(r['submission_steps']))+'\n\nPROVIDER QUESTIONS (NOT SENT)\n'+'\n'.join('- '+x for x in r['provider_questions'])+'\n'


def chrome(text,name):
    if name=='index.html':return text
    text=re.sub(r'<!-- program-chrome-start -->.*?<!-- program-chrome-end -->','',text,flags=re.S)
    active=name if name in [n for n,_ in NAV] else GROUPS.get(name,'report.html')
    nav=''.join('<a href="'+n+'"'+(' aria-current="page"' if n==active else '')+'>'+label+'</a>' for n,label in NAV)
    header='<!-- program-chrome-start --><a class="program-skip" href="#program-content">Skip to content</a><header class="program-header"><div class="program-university-bar"><div>THE UNIVERSITY OF ARIZONA</div></div><div class="program-top"><a class="program-brand" href="program.html">College of Information Science<small>Computing for teaching · planning proposal</small></a><span class="program-pill">Plan in preparation</span></div><nav class="program-nav" aria-label="Program navigation">'+nav+'</nav></header><!-- program-chrome-end -->'
    text=text.replace('</head>','<!-- program-chrome-start --><link rel="stylesheet" href="program.css"><!-- program-chrome-end --></head>')
    if '<main' not in text:
        text=text.replace('<body>','<body><main id="program-content">').replace('</body>','</main></body>')
    text=text.replace('<body>','<body>'+header)
    text=re.sub(r'<main(?![^>]*\bid=)', '<main id="program-content"',text,count=1)
    text=re.sub(r'<main([^>]*)>',lambda m: '<main'+m[1]+' class="program-main">' if 'class=' not in m[1] else m[0],text,count=1)
    footer='<!-- program-chrome-start --><footer class="program-footer"><p><strong>Planning proposal.</strong> ACCESS is the intended CPU/GPU classroom route. Provider measurements, awards and classroom admission remain pending; Greg has ten hours/week total and zero cash budget.</p><p><a href="timeline.html">Staged plan</a> · <a href="resource-library.html">Working tools</a> · <a href="report.html">Full report &amp; evidence</a> · <a href="index.html">Five-slide talk</a></p><p>Greg Chism · UArizona Information Science · Design and Classroom 50 assessment updated October 13, 2026. Evidence retains its own check dates.</p></footer><script src="program.js"></script><!-- program-chrome-end -->'
    return text.replace('</body>',footer+'</body>')


def build():
    p=json.loads((ROOT/'site/education-compute-pilot.json').read_text());d=json.loads((DEST/'evidence.json').read_text());e=d['evidence'];b=p['budget']
    def refs(keys):return ' · '.join('<a href="evidence.html#'+ESC(k)+'">'+ESC(e[k]['title'])+'</a>' for k in keys)
    def links(rows):return '<div class="pg-actions">'+''.join('<a class="pg-link" href="'+ESC(url,quote=True)+'">'+ESC(label)+' ↗</a>' for label,url in rows)+'</div>'
    def page(title,body):
        base='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'''+ESC(title)+''' · Computing for teaching</title><meta name="description" content="A proposed UArizona data science and MLIS classroom pilot: staged plan, classroom tools, hours, request drafts and research evidence."><link rel="icon" href="../assets/favicons/talk.svg" type="image/svg+xml"><link rel="icon" href="../assets/favicons/talk-32.png" type="image/png" sizes="32x32"><link rel="apple-touch-icon" href="../assets/favicons/talk-180.png" sizes="180x180"></head><body><main class="program-main" id="program-content">'''+body+'''</main><script>window.programData='''+json.dumps(p,ensure_ascii=False).replace('<','\\u003c')+'''</script></body></html>'''
        return base
    visual='''<figure class="pg-visual"><svg viewBox="0 0 450 330" role="img" aria-label="Campus AWS CPU component tests and free GPU benchmarks precede the ACCESS CPU and GPU classroom pilot. CloudBank is conditional."><rect x="10" y="10" width="205" height="76" rx="0" fill="#1E5288"/><rect x="235" y="10" width="205" height="76" rx="0" fill="#1E5288"/><g fill="#fff" text-anchor="middle" font-family="system-ui,sans-serif"><text x="112" y="40" font-size="18" font-weight="650">Campus AWS</text><text x="112" y="65" font-size="14">CPU component tests only</text><text x="338" y="40" font-size="18" font-weight="650">Free GPUs</text><text x="338" y="65" font-size="14">Pre-pilot benchmarks</text></g><path d="M112 86V106H338V86M225 106V126" fill="none" stroke="#81CEEB" stroke-width="3"/><rect x="65" y="126" width="320" height="82" rx="0" fill="#ffffff"/><text x="225" y="157" text-anchor="middle" fill="#0C234B" font-size="22" font-weight="700">ACCESS CPU + GPU</text><text x="225" y="184" text-anchor="middle" fill="#0C234B" font-size="14">Size request · confirm award · replay</text><path d="M225 208V229" stroke="#81CEEB" stroke-width="3"/><rect x="65" y="229" width="320" height="67" rx="0" fill="#AB0520"/><text x="225" y="257" text-anchor="middle" fill="#fff" font-size="20" font-weight="650">DS + MLIS classroom pilot</text><text x="225" y="280" text-anchor="middle" fill="#fff" font-size="13">Support · recovery · exports</text><text x="225" y="321" text-anchor="middle" fill="#ffffff" font-size="13">CloudBank: conditional managed option</text></svg><figcaption>Test and benchmark first; the classroom route is ACCESS.</figcaption></figure>'''
    panels=''.join('<article class="pg-audience-panel" data-audience-panel="'+a['id']+'"'+(' hidden' if a['id']!='administrators' else '')+'><p class="pg-kicker">'+ESC(a['name'])+'</p><h3>'+ESC(a['headline'])+'</h3><p>'+ESC(a['body'])+'</p>'+links(a['links'])+'</article>' for a in p['audiences'])
    tabs='<div class="pg-tabs" role="group" aria-label="Choose an audience">'+''.join('<button type="button" data-audience="'+a['id']+'" aria-pressed="'+str(a['id']=='administrators').lower()+'">'+ESC(a['name'])+'</button>' for a in p['audiences'])+'</div>'
    overview=overview_view(p,visual,tabs,panels)
    phases=''.join('<article class="pg-phase"><p class="pg-kicker">'+ESC(ph['when'])+'</p><div><h3>'+ESC(ph['title'])+'</h3><p>'+ESC(ph['body'])+'</p><p><strong>Exit evidence:</strong> '+ESC(ph['exit'])+'</p></div></article>' for ph in p['phases'])
    coursecards=''.join('<article class="pg-card" id="course-'+c['id']+'"><p class="pg-kicker">40 planned students · proposed course candidate</p><h3>'+ESC(c['name'])+'</h3><p><strong>Proposed candidate:</strong> <a href="'+ESC(c['public_course_url'],quote=True)+'">'+ESC(c['candidate'])+'</a></p><p class="pg-small">'+ESC(c['selection'])+'</p><p><strong>Core assignment:</strong> '+ESC(c['assignment'])+'</p><p><strong>Inputs:</strong> '+ESC(c['data'])+'</p><p><strong>Environment:</strong> '+ESC(c['tools'])+'</p>'+('<p><strong>Onboarding:</strong> '+ESC(c['onboarding'])+'</p>' if c.get('onboarding') else '')+'<ul>'+''.join('<li>'+ESC(x)+'</li>' for x in c['outcomes'])+'</ul><p><strong>Acceptance:</strong> '+ESC(c['acceptance'])+'</p><details><summary>Representative 15-week activity sequence</summary>'+''.join('<p><strong>'+ESC(w)+':</strong> '+ESC(v)+'</p>' for w,v in c['units'])+'</details><p class="pg-small">'+ESC(c['optional'])+'</p></article>' for c in p['courses'])
    staffing=''.join('<tr><th scope="row" class="pg-role">'+ESC(r['role'])+'<span class="pg-small" style="display:block">'+ESC(r['owner'])+'</span></th><td>'+str(r['people'])+'</td><td>'+str(r['hours'])+'</td><td>'+ESC(r['duty'])+'</td></tr>' for r in b['roles']+b['separate_roles'])
    plan='''<p class="pg-kicker">Concrete pilot plan · draft</p><h1>Two courses.<br>One dependable baseline.</h1><p class="pg-lead">First test CPU components on campus AWS and benchmark GPUs on free resources. Then size and obtain ACCESS CPU/GPU access, run a ten-volunteer canary, and admit 80 seats after the provider, institutional and workload checks pass.</p><p class="pg-note warning">The proposed candidates are INFO 521 and LIS 671. Future offering, instructor consent, term and enrollment are not confirmed here. The schedule is relative to a future approved term. ACCESS is the CPU/GPU classroom route. Keep equivalent CPU-assessed activities; GPU workloads must pass pre-pilot benchmarking and target-resource verification. Campus AWS remains component-testing only.</p>'''+links([('Download the pilot brief PDF','pilot-brief.pdf'),('Full plan text','pilot-plan.txt'),('Pre-class checks','readiness.html')])+'''<section id="courses"><h2>What students will do</h2><div class="pg-grid">'''+coursecards+'''</div></section><section><h2>Who does the work</h2><p>The seven Greg rows divide a single ten-hour weekly envelope; they are functions, not seven hires. TA and course-lead hours are separate, and course leads need no salary. No college sponsor/finance role is included. An independent backup must be a distinct person; that coverage is currently unfilled.</p><div class="pg-table"><table><thead><tr><th>Role</th><th>People</th><th>Added pilot hours</th><th>Responsibility</th></tr></thead><tbody>'''+staffing+'''</tbody></table></div><p class="pg-small">Hours cover the modeled 23-week preparation/teaching/close period. Regular course instruction and grading are excluded; no role is appointed or funded by this table. <a href="budget.html">See weekly effort and grant dependencies ↗</a>.</p></section><section><h2>Stage the commitment</h2>'''+phases+'''</section><section><h2>Support and continuity in practice</h2><div class="pg-grid"><article class="pg-card"><h3>Help and escalation</h3><p>Potential TA support is six combined hours/week outside Greg’s ten hours. Greg’s teaching-phase split includes four service-operations hours plus six hours for all other work. Independent backup coverage is unfilled. Publish feasible windows only after actual support commitments; no 24/7 promise.</p><p>TA/course lead → primary operator → backup/provider → service owner. A class-blocking issue triggers the small-data CPU fallback and an assignment accommodation, not an unapproved provider purchase.</p></article><article class="pg-card"><h3>Files, grades and preservation</h3><p>Provider student home → approved independent backup/export destination → restore on another environment. Keep authoritative rosters and grades in approved institutional/LMS systems. Repository deposits contain only rights-cleared, approved public outputs.</p><p>Proposed RPO: 24 hours. Proposed RTO: one business day. Test both; a snapshot or cold archive alone does not establish either.</p></article></div></section><section><h2>How the pilot will be judged</h2><ul>'''+''.join('<li>'+ESC(x)+'</li>' for x in p['evaluation'])+'''</ul><p class="pg-note">Scale only after course leads and Greg review actual costs, support demand, reliable access and instructional evidence. A working platform or grant award alone does not prove educational benefit.</p></section><p class="pg-refs">Planning evidence: '''+refs(p['source_keys'])+'''</p>'''
    hoursrows=''.join('<tr><th scope="row">'+ESC(r['role'])+'</th><td>'+str(r['preparation_weekly'])+'</td><td><input type="number" name="weekly-'+r['id']+'" min="0" max="40" step="0.5" value="'+str(r['weekly'])+'" aria-label="'+ESC(r['role'])+' teaching-week hours" required></td><td>'+str(r['close_weekly'])+'</td><td>'+str(r['hours'])+'</td></tr>' for r in b['roles'])
    grantcards=''.join('<article class="pg-card"><h3><a href="'+ESC(g['url'],quote=True)+'">'+ESC(g['name'])+' ↗</a></h3><p>'+ESC(g['work'])+'</p><p class="pg-small">'+ESC(g['boundary'])+'</p></article>' for g in b['grant_lanes'])
    budgetbody='<p class="pg-kicker">Hours only · no salary arithmetic</p><h1>Ten hours a week. Zero cash budget.</h1><p class="pg-lead">Greg’s entire allocation, benchmarking, operations, review and grant work must fit ten hours/week. TA and course-lead effort is separate; course leads need no salary. No college sponsor/finance role is included.</p><p class="pg-note">'+ESC(b['basis'])+'</p>'+links([('Hours CSV','pilot-hours.csv'),('Grant work-package summary','grant-work-packages.txt'),('Pilot brief PDF','pilot-brief.pdf')])+'<form id="effortForm"><section><h2>Potential roles inside Greg’s time</h2><p>Weekly preparation and close splits each total ten hours. Edit teaching-week hours to check capacity; these browser-only scenarios appoint nobody and approve no funding.</p><div class="pg-table"><table><thead><tr><th>Function (Greg)</th><th>Prep h/week</th><th>Teach h/week</th><th>Close h/week</th><th>Default 23-week hours</th></tr></thead><tbody>'+hoursrows+'</tbody></table></div><p id="effortError" class="pg-error" role="alert"></p><div class="pg-actions"><button type="button" id="resetEffort">Reset hours</button><button type="button" id="downloadEffort">Download weekly scenario CSV</button></div><p class="pg-note" id="effortCapacity" aria-live="polite">Teaching-week plan: ten of ten hours.</p></section></form><section><h2>Hours outside Greg’s envelope</h2><div class="pg-grid">'+''.join('<article class="pg-card"><h3>'+ESC(r['role'])+'</h3><p>'+ESC(r['duty'])+'</p><p><strong>'+str(r['hours'])+' total hours</strong> · '+ESC(r['owner'])+'</p></article>' for r in b['separate_roles'])+'</div><p class="pg-note warning">'+ESC(b['gaps'])+'</p></section><section><h2>Fund necessary spending through eligible grants</h2><p>'+ESC(b['funding'])+'</p><p>The EduCloud plan separates public-good development, stewardship, evaluation, training and recurring service duties. This zero-budget pilot may proceed only within existing approved resources and available hours. For any paid need, confirm an awarded grant, allowable activities and term coverage first; do not count one activity against multiple awards.</p><div class="pg-grid">'+grantcards+'</div><p class="pg-note">IUSE’s undergraduate scope is distinct from these graduate course candidates. Grant prospects are not received funds. No cash estimates or personal purchases are proposed.</p></section>'
    r=p['request'];rt=request_text(p)
    requestbody='<p class="pg-kicker">ACCESS CPU + GPU allocation · not submitted</p><h1>Size the allocation from measured work.</h1><p class="pg-lead">ACCESS will be the classroom route for both CPU and GPU. Campus UITS/AWS is only for CPU component tests; free GPUs provide benchmark evidence before piloting. CloudBank through ACCESS remains conditional.</p><p class="pg-note warning">The 80-seat pilot is a starting workload, not a completed large request. GPU measurements, additional cohorts, tier, numeric provider units, PI/course/term fields and required attachments remain incomplete.</p>'+links([('ACCESS draft PDF','access-allocation-request.pdf'),('ACCESS draft text','access-allocation-request.txt'),('GPU benchmark protocol','gpu-benchmark.html'),('Conditional CloudBank text','cloudbank-access-request.txt'),('Conditional CloudBank PDF','cloudbank-access-request.pdf')])+'<section><h2>What the designated PI will need</h2><ul class="pg-checklist">'+''.join('<li>'+ESC(x)+'</li>' for x in r['attachments'])+'</ul><p class="pg-refs">'+refs(['pilotaccessprepare','access'])+'</p></section><section><h2>Draft form text and resource plan</h2><p>Discover explicitly supports large classes; the appropriate tier depends on measured demand. Large does not automatically mean Maximize. Review the public overview before submission.</p><div class="pg-actions pg-no-print"><button id="copyRequest" type="button">Copy draft request</button></div><p id="copyStatus" class="pg-small" role="status"></p><div class="pg-request" id="requestText">'+ESC(rt)+'</div></section><section><h2>CloudBank feasibility branch</h2><p>The documented managed Classroom route uses Explore ACCESS. It does not establish GPU availability for this plan, and general commercial-cloud broker terms are separate. Confirm CPU/GPU coverage, accounting, dates and responsibilities before changing implementation. The saved CPU-only CloudBank concept is explicitly conditional.</p><p class="pg-refs">'+refs(['assesscloudbank','assesscbgpu','assesscbscope'])+'</p></section><section><h2>Submission remains a human action</h2><p>This site submits nothing. Provider questions are unsent; the designated PI must review the live portal, attachments and award scope. The award is followed by target-system replay and classroom readiness checks.</p></section>'
    filters=lambda group,rows,search=False:'<div data-filter-group="'+group+'">'+('<label class="pg-small">Find a topic<input style="display:block;width:100%;padding:10px;font:inherit;margin:10px 0" type="search" aria-label="Search resource library" placeholder="MESA, free hosting, data, evidence…"></label>' if search else '')+'<div class="pg-tabs" role="group" aria-label="Filter '+group+'">'+''.join('<button type="button" data-filter="'+key+'" aria-pressed="'+str(key=='all').lower()+'">'+label+'</button>' for key,label in rows)+'</div><p class="pg-small" data-filter-count aria-live="polite"></p></div>'
    checkcards=''.join('<article class="pg-card" data-filter-item data-category="'+g['category'].lower()+'" id="check-'+g['id']+'"><p class="pg-kicker">'+ESC(g['category']+' · '+g['when'])+'</p><p class="pg-status">'+ESC(g['status'])+'</p><h3>'+str(i+1)+' · '+ESC({'benchmark':'CPU tests and GPU benchmarks','scope':'Scope, owners and funds','provider':'Provider fit and award','accounts':'Login, isolation and removal','software':'Complete CPU assignment','capacity':'Class concurrency','save':'Save, restart and export','grades':'Submission and grade receipts','data':'Data destinations and rights','accessibility':'Accessible essential workflows','recovery':'Independent restore','support':'Support and fallback','exit':'Expiry and teach-out'}[g['id']])+'</h3><p><strong>Owner:</strong> '+ESC(g['owner'])+'</p><p>'+ESC(g['criterion'])+'</p><p><strong>Evidence required:</strong> '+ESC(g['evidence'])+'</p><p><strong>Stop if:</strong> '+ESC(g['stop'])+'</p></article>' for i,g in enumerate(p['checks']))
    readiness='''<p class="pg-kicker">Proposed acceptance register · no checks run</p><h1>Before this becomes required coursework.</h1><p class="pg-lead">Thirteen checks, with an accountable owner and concrete evidence. The current status is <strong>0 of 13 confirmed</strong>. An allocation alone does not change that status.</p><p class="pg-note">Targets such as five-minute p95 login, 24-hour RPO and one-business-day recovery/response are proposed acceptance criteria to negotiate and measure. They are not provider guarantees or achieved service levels.</p>'''+links([('Download review register CSV','pilot-readiness.csv'),('Pilot plan','pilot-plan.html'),('Existing route assessment','classroom-assessment.html')])+filters('readinessCards',[('all','All checks'),('access','Access & capacity'),('teaching','Teaching'),('recovery','Recovery & exit'),('operations','Operations')])+'''<div class="pg-grid" id="readinessCards">'''+checkcards+'''</div><section><h2>Who admits the course</h2><p>Each course lead signs off the assignment, accessibility and grading path; the operator and backup sign off access/capacity and recovery; IT/privacy approves data destinations; the service owner and college sponsor verify funding, coverage and remaining risks. Record names, dates and private supporting artifacts in the institutional register, not this public website. Classroom admission requires all applicable checks, or a reviewed substitute that demonstrably meets the same need.</p><p>A failed core check keeps the full course out of the pilot. A failed optional component stays out while the CPU baseline proceeds if its checks passed. Recheck affected gates after image, policy, staffing or provider changes.</p></section>'''
    library=tools_view()
    pages={'program.html':('Reliable computing for teaching',overview),'pilot-plan.html':('Two-course pilot plan',plan),'budget.html':('Hours and grant dependencies',budgetbody),'access-request.html':('ACCESS CPU + GPU request draft',requestbody),'readiness.html':('Pre-class checks',readiness),'resource-library.html':('Classroom tools',library),'timeline.html':('Staged program plan',timeline_view(p)),'report.html':('Full report and evidence',report_hub(len(e)))}
    bench=p['benchmark']
    benchcards=''.join('<article class="pg-card"><h3>'+ESC(x['name'])+'</h3><p><strong>'+ESC(x['role'])+'</strong></p><p>'+ESC(x['limits'])+'</p>'+('<p class="pg-refs">'+refs(x['sources'])+'</p>' if x['sources'] else '')+'</article>' for x in bench['resources'])
    benchrows=[dict(workload_id=x['id'],workload=x['workload'],platform=x['platform'],status='Not run',date_utc='',environment_manifest='',data_sha256='',device_and_fraction='',vram_gb='',cpu_ram_gb='',quota_before_after='',setup_seconds='',run_seconds='',peak_memory_gb='',correctness='',checkpoint_resume='',export_reopen='',failure_reason='',charged_units='',notes=x['purpose']) for x in bench['workloads']]
    with (DEST/'gpu-benchmark-results.csv').open('w',newline='') as file:
        writer=csv.DictWriter(file,fieldnames=list(benchrows[0]),lineterminator='\n');writer.writeheader();writer.writerows(benchrows)
    benchbody='<p class="pg-kicker">Runnable components · provider benchmarks not run</p><h1>Measure first. Request CPU and GPU together.</h1><p class="pg-lead">Campus UITS/AWS tests CPU components only. Free GPU resources establish a bounded workload envelope. ACCESS is the intended CPU/GPU classroom route; replay on the awarded system verifies fit before class.</p>'+links([('Runnable benchmark bundle','classroom-benchmarks.zip'),('DS GPU notebook','benchmarks/ds-gpu-benchmark.ipynb'),('MLIS GPU notebook','benchmarks/mlis-gpu-benchmark.ipynb'),('Open DS in Colab','https://colab.research.google.com/github/Gchism94/talks/blob/main/docs/education-compute/benchmarks/ds-gpu-benchmark.ipynb'),('Open MLIS in Colab','https://colab.research.google.com/github/Gchism94/talks/blob/main/docs/education-compute/benchmarks/mlis-gpu-benchmark.ipynb'),('CPU runner','benchmarks/cpu_benchmarks.py'),('Run guide','benchmarks/README.txt'),('ACCESS sizing tool','benchmarks/size_access.py'),('Blank provider results register','gpu-benchmark-results.csv'),('ACCESS draft','access-request.html'),('Admission checks','readiness.html')])+'<div class="pg-grid">'+benchcards+'</div><section><h2>What to measure</h2>'+''.join('<article class="pg-card"><p class="pg-kicker">Not run · '+ESC(x['platform'])+'</p><h3>'+ESC(x['workload'])+'</h3><p>'+ESC(x['purpose'])+'</p></article>' for x in bench['workloads'])+'</section><section><h2>Reproducible protocol</h2><ol>'+''.join('<li>'+ESC(x)+'</li>' for x in bench['protocol'])+'</ol><p class="pg-note">Owner: '+ESC(bench['owner'])+'. The provider register is blank. Local synthetic CPU controls passed; AWS, CUDA/Kaggle/Colab and target ACCESS measurements remain pending. See the downloadable run guide for exact commands and evidence scope. Passing a free GPU run does not reserve class capacity.</p></section>'
    pages['gpu-benchmark.html']=('Pre-pilot CPU tests and GPU benchmarks',benchbody)
    pages['classroom50.html']=('Classroom 50 successor assessment',assessment_view(d))
    for name,(title,content) in pages.items():(DEST/name).write_text(page(title,content))
    (DEST/'program.css').write_bytes((ROOT/'site/education-compute-program.css').read_bytes());(DEST/'program.js').write_bytes((ROOT/'site/education-compute-program.js').read_bytes())
    (DEST/'pilot-program.json').write_text(json.dumps(p,indent=2,ensure_ascii=False)+'\n');(DEST/'access-allocation-request.txt').write_text(rt);(DEST/'cloudbank-access-request.txt').write_text(request_text(p,p['cloudbank_request']))
    plantext=p['title']+'\n'+p['status']+'\n\n'+p['decision']+'\n\nCOURSE CONCEPTS\n'
    for c in p['courses']:plantext+='\n'+c['name']+'\n'+c['assignment']+'\n'+c['data']+'\n'+c['tools']+'\nAcceptance: '+c['acceptance']+'\nOptional: '+c['optional']+'\n'
    plantext+='\nPHASES\n'
